/// <summary>
/// Hard-removes a single attendee from a class (for booking mistakes). Refunds
/// any package credit that was consumed, deletes the attendance row entirely,
/// and frees the seat(s) on the session. Unlike a CANCELLED status this leaves
/// no lingering row on the roster.
/// </summary>
public async Task<bool> RemoveAttendanceAsync(string attendanceId)
{
    var att = await _attendances.Find(a => a.Id == attendanceId).FirstOrDefaultAsync();
    if (att is null) return false;

    // Refund any consumed package credit — ledger-driven, with the legacy
    // PackageInstanceId fallback (mirrors the session-cancel refund path).
    var (refunded, hasLedgerTrail) = await _walletService.RefundCreditByAttendanceWithTrailAsync(att.Id!);
    if (!refunded && !hasLedgerTrail && !string.IsNullOrEmpty(att.PackageInstanceId))
        await _walletService.RefundCreditAsync(
            att.PackageInstanceId, att.RescheduledFromAttendanceId ?? att.Id!);

    // Delete the row and free the seat(s).
    await _attendances.DeleteOneAsync(a => a.Id == attendanceId);
    if (!string.IsNullOrWhiteSpace(att.CalendarSessionId))
    {
        var seats = att.Quantity <= 0 ? 1 : att.Quantity;
        await _sessions.UpdateOneAsync(
            s => s.Id == att.CalendarSessionId,
            Builders<CalendarSession>.Update.Inc(s => s.CurrentBookings, -seats));
        // Never let the counter go negative.
        await _sessions.UpdateOneAsync(
            s => s.Id == att.CalendarSessionId && s.CurrentBookings < 0,
            Builders<CalendarSession>.Update.Set(s => s.CurrentBookings, 0));
        // SPM-98 — if this was a duo PRIVATE whose Capacity was bumped 1→2 and no
        // active seats remain, restore Capacity to 1 so the freed 1-on-1 slot
        // can't later be double-booked by two unrelated single bookers.
        await RestorePrivateCapacityIfEmptyAsync(att.CalendarSessionId);
    }
    return true;
}

public async Task<bool> UpdateAttendanceStatusAsync(string attendanceId, string status)
{
    var update = Builders<Attendance>.Update.Set(a => a.Status, status);
    var result = await _attendances.UpdateOneAsync(a => a.Id == attendanceId, update);
    if (result.ModifiedCount == 0) return false;

    // ── P5-PWA — push the instructor when a customer no-shows. ─────────────
    // Fire-and-forget so a Mongo/staff lookup hiccup can't fail the
    // primary status update from the admin's perspective.
    if (string.Equals(status, "NO_SHOW", StringComparison.OrdinalIgnoreCase))
    {
        _ = Task.Run(async () =>
        {
            try
            {
                var att = await _attendances.Find(a => a.Id == attendanceId).FirstOrDefaultAsync();
                if (att is null || string.IsNullOrWhiteSpace(att.CalendarSessionId)) return;
                var session = await _sessions.Find(s => s.Id == att.CalendarSessionId).FirstOrDefaultAsync();
                if (session is null) return;
                var instructor = await _staff.Find(s => s.Id == session.InstructorId).FirstOrDefaultAsync();
                if (instructor is null || string.IsNullOrWhiteSpace(instructor.UserId)) return;

                var payload = new PushPayload

    if (session.Status != "SCHEDULED") throw new BusinessRuleException("BOOKING.SESSION_NOT_SCHEDULED", "This session is not available for booking.");
    // A class that has already started is no longer bookable (guards a stale
    // booking page that still shows a class which began after it was loaded).
    if (session.StartTime <= DateTime.UtcNow)
        throw new BusinessRuleException("BOOKING.SESSION_STARTED", "This class has already started and can no longer be booked.");
    // SPM-91 — private sessions are hidden from the public booking page and
    // must not be reservable through the public reserve path. Surface the
    // same "not found" code so the existence of a private session isn't
    // disclosed. Internal booking (AdminAddStudent / WalkIn) is unaffected.
    if (!session.IsPublic) throw new NotFoundException("BOOKING.SESSION_NOT_FOUND", "Session not found.");

    if (quantity <= 0) quantity = 1;

    // ── P5-S01: Reservation deduplication ────────────────────────────
    // Check if this client already has an active RESERVED attendance for
    // this exact session. If so, refresh its timestamp and return it
    // instead of creating a new one. This prevents the
    // multiple-checkout-visits capacity leak.
    // (Looked up before the PRIVATE quantity clamp so a duo upgrade on a
    //  re-reservation isn't mistaken for someone else occupying the slot.)
    var existingReserved = await _attendances.Find(a =>
        a.CalendarSessionId == sessionId &&
        a.ClientId == clientId &&
        a.Status == "RESERVED"
    ).FirstOrDefaultAsync();

    // Quantity invariants:
    //   • SPM-98 "Make it a Duo Class" — a PRIVATE session may be booked as a
    //     duo (2 seats) by a single booker who covers both seats. We mirror the
    //     existing DUO format (capacity 2): the booker's single attendance carries
    //     Quantity=2, CurrentBookings is incremented by 2, and 2 credits / 2× the
    //     drop-in are charged via the same multi-seat path GROUP bookings use.
    //     A PRIVATE session is created with Capacity=1, so for the duo case we bump
    //     the session's effective capacity to 2 to make room for the second seat.
    //     Anything other than the 1-seat or duo (2-seat) case on a PRIVATE session
    //     is clamped to 1 so a malicious payload can't over-book a 1-to-1 class.
    if (session.Format == "PRIVATE")
    {
        // The booker may take the whole 1-on-1 slot as a duo only when nobody
        // ELSE holds a seat. Seats this client already reserved (the dedup row
        // we're about to refresh) don't count against them, so a 1→2 upgrade on
        // a re-reservation is still allowed.
        var othersBooked = session.CurrentBookings - (existingReserved?.Quantity ?? 0);
        if (quantity == 2 && othersBooked <= 0)
        {
            // Mirror DUO capacity-2: lift the 1-on-1 session's capacity to 2 so
            // the duo's second seat fits the shared capacity guard below. Only
            // raise it — never shrink an admin-configured larger capacity.
            if (session.Capacity < 2)
            {
                await _sessions.UpdateOneAsync(
                    s => s.Id == sessionId,
                    Builders<CalendarSession>.Update.Set(s => s.Capacity, 2));
                session.Capacity = 2;
            }
        }
        else
        {
            quantity = 1;
        }
    }

    if (existingReserved != null)
    {
        // Refresh the reservation timestamp so the cleanup job doesn't
        // expire it while the customer is still on the checkout page.
        var refreshUpdate = Builders<Attendance>.Update
            .Set(a => a.ReservedAt, DateTime.UtcNow)
            .Set(a => a.ClientName, clientName)
            .Set(a => a.ClientPhone, clientPhone)
            .Set(a => a.ClientEmail, clientEmail);

        // Update quantity if changed — adjust session capacity accordingly.
        if (existingReserved.Quantity != quantity)
        {
            var diff = quantity - existingReserved.Quantity;
            if (diff > 0)
            {
                // Atomically claim the extra seat(s) — guards the same race as a fresh reserve.
                if (!await TryClaimSessionCapacityAsync(sessionId, diff))
                {
                    var spotsLeft = Math.Max(0, session.Capacity - session.CurrentBookings);
                    throw new BusinessRuleException(
                        "BOOKING.INSUFFICIENT_CAPACITY",
                        $"Only {spotsLeft} spot(s) remaining — cannot reserve {quantity}.");
                }
            }
            else
            {
                // Releasing seat(s) — no capacity guard needed.
                await _sessions.UpdateOneAsync(s => s.Id == sessionId,
                    Builders<CalendarSession>.Update.Inc(s => s.CurrentBookings, diff));
            }
            refreshUpdate = refreshUpdate.Set(a => a.Quantity, quantity);
        }

        if (!string.IsNullOrWhiteSpace(packageInstanceId))
            refreshUpdate = refreshUpdate.Set(a => a.PackageInstanceId, packageInstanceId);
        if (!string.IsNullOrWhiteSpace(goals))
            refreshUpdate = refreshUpdate.Set(a => a.Goals, goals);
        if (!string.IsNullOrWhiteSpace(equipmentType))
            refreshUpdate = refreshUpdate.Set(a => a.EquipmentType, equipmentType);

        await _attendances.UpdateOneAsync(a => a.Id == existingReserved.Id, refreshUpdate);

        // Return the refreshed attendance — the caller gets the same
        // attendanceId it would have gotten from a fresh insert.
        existingReserved.ReservedAt = DateTime.UtcNow;
        existingReserved.ClientName = clientName;
        existingReserved.ClientPhone = clientPhone;
        existingReserved.ClientEmail = clientEmail;
        if (existingReserved.Quantity != quantity)
            existingReserved.Quantity = quantity;
        return existingReserved;
    }

    // ── No existing reservation — create fresh ───────────────────────
    // Atomically claim the seat(s) up-front so two customers racing for the
    // last spot can't both succeed (this used to be a check-then-Inc race).
    // A failed claim means full or no longer SCHEDULED.
    if (!await TryClaimSessionCapacityAsync(sessionId, quantity))
    {
        var spotsLeft2 = Math.Max(0, session.Capacity - session.CurrentBookings);
        // P4-S02 — Typed; the frontend branches on BOOKING.CAPACITY_REACHED to offer waitlist.
        if (spotsLeft2 <= 0)
            throw new BusinessRuleException("BOOKING.CAPACITY_REACHED", "Class is at full capacity.");
        // Issue #3 — multi-seat: surface remaining spots for a friendlier message.
        throw new BusinessRuleException(
            "BOOKING.INSUFFICIENT_CAPACITY",
            $"Only {spotsLeft2} spot(s) remaining — cannot reserve {quantity}.");
    }

    // Multiple bookings per session allowed (guests, rebooking, etc.).

    // ── Booking-page offer attach ────────────────────────────────────
    // The claimed offer (if any) is recorded on the booking so reception
    // sees it, reporting can count it, and the revenue pipeline can net the
    // discount. BRING_A_FRIEND books 2 seats but charges 1 — the free seat's
    // fee is stored as the promo discount so class revenue reflects one seat.
    var offer = (offerType ?? "").Trim().ToUpperInvariant();
    var isBringAFriend = offer == "BRING_A_FRIEND" && quantity >= 2;
    decimal? promoDiscount = null;
    if (isBringAFriend)
        promoDiscount = session.DropInPrice; // one seat free
    var normalisedPromo = string.IsNullOrWhiteSpace(promoCode) ? null : promoCode.Trim().ToUpperInvariant();

    var attendance = new Attendance
    {
        CalendarSessionId = sessionId,
        ClientId = clientId,
        PackageInstanceId = packageInstanceId,
        Status = "RESERVED", // NOT deducting credits — only reserved
        BookedAt = DateTime.UtcNow,
        ReservedAt = DateTime.UtcNow,
        BookingReference = GenerateBookingReference(),
        ClientName = clientName,
        ClientPhone = clientPhone,
        ClientEmail = clientEmail,
        BookingSource = "ONLINE",
        Goals = goals,
        EquipmentType = equipmentType ?? session.EquipmentType,
        Quantity = quantity,
        MarketingSource = string.IsNullOrWhiteSpace(marketingSource) ? null : marketingSource.Trim().ToLowerInvariant(),
        MarketingDetail = string.IsNullOrWhiteSpace(marketingDetail) ? null : marketingDetail.Trim(),
        PromoCode = normalisedPromo,
        IsBringAFriend = isBringAFriend,
        PromoDiscountAmount = promoDiscount,
    };
    // Seat(s) already claimed atomically above — just persist the attendance,
    // rolling the claim back if the insert fails so capacity never drifts.
    try
    {
        await _attendances.InsertOneAsync(attendance);
    }
    catch
    {
        await ReleaseSessionCapacityAsync(sessionId, quantity);
        throw;
    }

    // A genuine ONLINE reservation ends the client's lapse — clear the win-back
    // throttle (also cleared on Stripe confirmation in PaymentService).
    await ClearWinBackThrottleAsync(clientId);

    return attendance;
}

/// <inheritdoc />
public async Task<List<(string Source, int Count)>> GetBookingSourceBreakdownAsync(DateTime from, DateTime to)
{
    var rows = await _attendances
        .Find(Builders<Attendance>.Filter.And(
            Builders<Attendance>.Filter.Eq(a => a.BookingSource, "ONLINE"),
            Builders<Attendance>.Filter.Gte(a => a.BookedAt, from),
            Builders<Attendance>.Filter.Lt(a => a.BookedAt, to),
            Builders<Attendance>.Filter.Nin(a => a.Status, new[] { "CANCELLED", "LATE_CANCEL", "RESERVED" })))
        .Project(a => a.MarketingSource)
        .ToListAsync();

    return rows
        .GroupBy(s => string.IsNullOrWhiteSpace(s) ? "direct" : s!.Trim().ToLowerInvariant())
        .Select(g => (Source: g.Key, Count: g.Count()))
        .OrderByDescending(x => x.Count)
        .ToList();
}

/// <inheritdoc />
public async Task<bool> ReleaseReservationAsync(string attendanceId, string? clientId = null)
{
    // Build the filter — attendance must be RESERVED (not yet paid/confirmed).
    var filterBuilder = Builders<Attendance>.Filter;
    var filter = filterBuilder.Eq(a => a.Id, attendanceId) &
                 filterBuilder.Eq(a => a.Status, "RESERVED");

    // If clientId is provided, ownership-guard it so one customer can't
    // release another customer's reservation.
    if (!string.IsNullOrWhiteSpace(clientId))
        filter &= filterBuilder.Eq(a => a.ClientId, clientId);

    var attendance = await _attendances.Find(filter).FirstOrDefaultAsync();
    if (attendance == null) return false;

    // Mark as CANCELLED
    await _attendances.UpdateOneAsync(a => a.Id == attendance.Id,
        Builders<Attendance>.Update.Set(a => a.Status, "CANCELLED"));

    // Free the capacity slot(s)
    if (!string.IsNullOrWhiteSpace(attendance.CalendarSessionId))
    {
        var qty = Math.Max(1, attendance.Quantity);
        await _sessions.UpdateOneAsync(
            s => s.Id == attendance.CalendarSessionId,
            Builders<CalendarSession>.Update.Inc(s => s.CurrentBookings, -qty));

        // SPM-98 — restore the PRIVATE duo capacity bump. ReserveSpotAsync
        // raises a PRIVATE session's Capacity 1→2 to fit a duo's second seat.
        // If that duo is released/expired and no active (non-cancelled) seats
        // remain on the PRIVATE session, restore Capacity to 1 so the empty
        // 1-on-1 slot can't be double-booked by two unrelated single bookers.
        await RestorePrivateCapacityIfEmptyAsync(attendance.CalendarSessionId);
    }

    return true;
}

/// <summary>
/// SPM-98 — when a PRIVATE session whose Capacity was bumped to 2 for a duo
/// has no remaining active (non-cancelled) seats, restore Capacity to 1 so a
/// freed 1-on-1 slot cannot be double-booked by two unrelated single bookers.
/// </summary>
private async Task RestorePrivateCapacityIfEmptyAsync(string sessionId)
{
    var session = await _sessions.Find(s => s.Id == sessionId).FirstOrDefaultAsync();
    if (session == null) return;
    if (session.Format != "PRIVATE" || session.Capacity <= 1) return;

    // Count seats still held by active (non-cancelled) attendances.
    var activeSeats = await _attendances
        .Find(a => a.CalendarSessionId == sessionId && a.Status != "CANCELLED")
        .ToListAsync();
    var heldSeats = activeSeats.Sum(a => Math.Max(1, a.Quantity));

    // The session was found above, so a no-op write (same value / clearing an
    // already-clear override) is still a success — key off MatchedCount.
    return result.MatchedCount > 0;
}

public async Task<bool> UpdateSessionAsync(string sessionId, CalendarSession updated)
{
    // SPM-87 — load the existing session FIRST so we can detect an
    // instructor re-assignment (old vs new InstructorId) after the save.
    var existing = await _sessions.Find(s => s.Id == sessionId).FirstOrDefaultAsync();

    // SPM-122 — InstructorId is [BsonRepresentation(ObjectId)]; an empty string can't
    // serialize as an ObjectId. Normalize blank -> null before the Set().
    updated.InstructorId = string.IsNullOrWhiteSpace(updated.InstructorId) ? null : updated.InstructorId;

    var updateDef = Builders<CalendarSession>.Update
        .Set(s => s.InstructorId, updated.InstructorId)
        .Set(s => s.InstructorName, updated.InstructorName)
        .Set(s => s.ClassName, updated.ClassName)
        .Set(s => s.FocusArea, updated.FocusArea)
        .Set(s => s.DifficultyLevel, updated.DifficultyLevel)
        .Set(s => s.Capacity, updated.Capacity)
        .Set(s => s.StartTime, updated.StartTime)
        .Set(s => s.EndTime, updated.EndTime);

    var result = await _sessions.UpdateOneAsync(s => s.Id == sessionId, updateDef);

    // SPM-87 — notify the newly-assigned instructor (push + email-fallback)
    // only when the instructor actually changed, so no-op saves stay quiet.
    NotifyInstructorReassignedIfChanged(existing, updated);

    return result.ModifiedCount > 0;
}

public async Task<Attendance> AdminAddStudentAsync(string sessionId, string clientId, string clientName, string? clientPhone, int quantity = 1)
{
    var session = await _sessions.Find(s => s.Id == sessionId).FirstOrDefaultAsync();
    if (session == null) throw new NotFoundException("BOOKING.SESSION_NOT_FOUND", "Session not found.");

    // SPM-126 — The duplicate-booking guard is intentionally omitted here.
    // The owner wants admins to add the same client to a session more than once
    // (e.g. the client is bringing a guest, or buying a second seat at the desk).
    // Each add is a distinct Attendance row and bumps CurrentBookings by the seat
    // quantity. This mirrors WalkInCheckoutAsync, which by design also skips the
    // guard. The customer-facing BookClientAsync guard is unaffected.

    // Capacity guard — enforce even for admin adds. Accounts for the requested
    // quantity so a 2-seat add against 1 remaining spot is rejected.
    var requestedSeats = Math.Max(1, quantity);
    if (string.Equals(session.Format, "PRIVATE", StringComparison.OrdinalIgnoreCase))
    {
        // SPM-98 — Duo private. A PRIVATE session is created with Capacity=1 (a
        // 1-on-1 slot). The studio may instead run it as a DUO — two clients in
        // the same private session. Mirror ReserveSpotAsync's duo rule for the
        // admin/desk add path: clamp any private add to at most 2 seats, ensure
        // the class stays within the duo cap of 2 total, then lift the session's
        // Capacity 1→2 so the second seat (one booker taking ×2, OR a distinct
        // second client taking ×1) fits the atomic capacity guard below. Only ever
        // raise it — never shrink an admin-configured larger capacity.
        requestedSeats = Math.Min(requestedSeats, 2);
        var wouldHold = session.CurrentBookings + requestedSeats;
        if (wouldHold > 2)
            throw new BusinessRuleException("BOOKING.PRIVATE_DUO_MAX",
                "A private session can hold at most 2 people (duo). Remove a seat before adding another.");
        if (session.Capacity < wouldHold)
        {
            await _sessions.UpdateOneAsync(
                s => s.Id == sessionId,
                Builders<CalendarSession>.Update.Set(s => s.Capacity, 2));
            session.Capacity = 2;
        }
    }
    var spotsLeft = session.Capacity - session.CurrentBookings;
    if (spotsLeft <= 0)
        throw new BusinessRuleException("BOOKING.CAPACITY_REACHED", "This class is at full capacity.");
    if (requestedSeats > spotsLeft)
        throw new BusinessRuleException("BOOKING.CAPACITY_REACHED",
            $"Only {spotsLeft} spot{(spotsLeft == 1 ? "" : "s")} remaining. Cannot add {requestedSeats} seat{(requestedSeats == 1 ? "" : "s")}.");

    // SPM-120 — A manual admin/instructor add is an UNPAID booking that the studio
    // must collect for at the desk. Mirror the WalkInCheckout snapshot logic so the
    // POS "collect" card surfaces the correct outstanding balance instead of ₫0:
    // stamp PaymentMethod = PAY_AT_STUDIO and snapshot the amount due from the
    // session's drop-in price × seat quantity (defaults to 1). For a free class
    // (DropInPrice 0 or null) the due stays 0 so nothing is collected.
    // No invoice is created here — CollectStudioPaymentAsync creates and links one
    // at collect time via InvoiceLine.AttendanceId.
    var amountDue = (session.DropInPrice ?? 0m) * requestedSeats;

    var attendance = new Attendance
    {
        CalendarSessionId = sessionId,
        ClientId = clientId,
        Status = "BOOKED",
        BookedAt = DateTime.UtcNow,
        BookingReference = GenerateBookingReference(),
        ClientName = clientName,
        ClientPhone = clientPhone,
        BookingSource = "WALK_IN",
        PaymentMethod = "PAY_AT_STUDIO",
        AmountPaid = null,
        AmountDueAtStudio = amountDue,
        Quantity = requestedSeats,
    };
    // Atomically claim the seat(s) before persisting so concurrent adds/bookings can't overbook.
    if (!await TryClaimSessionCapacityAsync(sessionId, requestedSeats))
        throw new BusinessRuleException("BOOKING.CAPACITY_REACHED", "This class is at full capacity.");
    try
    {
        await _attendances.InsertOneAsync(attendance);
    }
    catch
    {
        await ReleaseSessionCapacityAsync(sessionId, requestedSeats);
        throw;
    }

    // P5-PWA — a manual desk booking (admin / receptionist / instructor add)
    // is a real booking too, so fire the same "New booking" push the customer
    // self-service path fires. Fire-and-forget: never fails the booking.
    // A genuine desk booking ends the client's lapse — clear the win-back throttle.
    await ClearWinBackThrottleAsync(clientId);
    FireAndForgetManualBookingPush(attendance, session);
    // Manual booking confirmation email (board: "Manual booking confirmation email").
    FireAndForgetManualBookingEmail(attendance, session);

    return attendance;
}

/// <summary>
/// Board card "Manual booking confirmation email" — send the customer the same
/// booking-confirmation email the online flow sends, but for MANUAL desk bookings
/// (staff/receptionist: credit book via BookClientAsync, POS walk-in via
/// WalkInCheckoutAsync, and admin/instructor add-to-session via AdminAddStudentAsync).
/// These paths create a BOOKED Attendance directly and never pass through
/// PaymentService, so they were the only booking-create routes that never emailed
/// the client.
///
/// No double-send: ONLINE bookings are created RESERVED by ReserveSpotAsync and are
/// emailed by PaymentService.FireAndForgetBookingEmail at the RESERVED→BOOKED
/// transition — they never reach these manual methods. Mirrors the exact
/// SendBookingConfirmationAsync arguments used by CustomerAuthService.
///
/// The manual create paths don't all denormalise the client's email/name onto the
/// Attendance (BookClientAsync/AdminAddStudentAsync only carry the ClientId), so the
/// email/name is resolved from the Client record when missing. Guarded on a non-empty
/// email; fire-and-forget so a mail failure never fails the booking.
/// </summary>
private void FireAndForgetManualBookingEmail(Attendance attendance, CalendarSession session)
{
    _ = Task.Run(async () =>
    {
        try
        {
            var email = attendance.ClientEmail;
            var name = attendance.ClientName;
            if (string.IsNullOrWhiteSpace(email) && !string.IsNullOrWhiteSpace(attendance.ClientId))
            {
                var client = await _clients.Find(c => c.Id == attendance.ClientId).FirstOrDefaultAsync();
                if (client is not null)
                {
                    if (string.IsNullOrWhiteSpace(email)) email = client.Email;
                    if (string.IsNullOrWhiteSpace(name)) name = client.FullName;
                }
            }

            if (string.IsNullOrWhiteSpace(email)) return; // no address on file — nothing to send

            await _emailService.SendBookingConfirmationAsync(
                email,
                string.IsNullOrWhiteSpace(name) ? "Customer" : name,
                attendance.BookingReference,
                session.ClassName,
                session.InstructorName,
                session.StartTime,
                session.Format,
                session.EndTime);
        }
        catch { /* email service already logs; never fail the booking over a mail error */ }
    });
}

/// <summary>
/// SPM — win-back throttle reset. A genuine new booking ends a client's
/// "lapse", so clear <see cref="Client.WinBackEmailSentAt"/> to re-arm a
/// future win-back email if they lapse again (RetentionReminderService).
/// Best-effort: a failure here must never fail the booking that triggered it.
/// </summary>
private async Task ClearWinBackThrottleAsync(string? clientId)
{
    if (string.IsNullOrWhiteSpace(clientId)) return;
    try
    {
        await _clients.UpdateOneAsync(
            c => c.Id == clientId,
            Builders<Client>.Update.Set(c => c.WinBackEmailSentAt, (DateTime?)null));
    }
    catch { /* throttle reset is best-effort; never break a booking */ }
}

/// <summary>
/// Mirror of PaymentService.FireAndForgetBookingPush for the manual admin/
/// receptionist/instructor add path, which doesn't go through PaymentService.
/// Notifies the session's instructor plus studio Admin/Manager/Owner roles.
/// </summary>
private void FireAndForgetManualBookingPush(Attendance attendance, CalendarSession session)
{
    _ = Task.Run(async () =>
    {
        try
        {
            var who = string.IsNullOrWhiteSpace(attendance.ClientName) ? "A client" : attendance.ClientName;
            var payload = new PushPayload
            {
                Title = "✨ New booking",
                Body  = $"{who} — {session.ClassName} · {StudioTime.Local(session.StartTime):ddd HH:mm}",
                Icon  = "/icons/icon-192.png",
                Badge = "/icons/icon-192.png",
                Url   = $"/admin/calendar?session={session.Id}",
                Tag   = $"booking-{attendance.Id}",
            };

            // The session's instructor (if their Staff row links to a login user).
            if (!string.IsNullOrWhiteSpace(session.InstructorId))
            {
                var instructor = await _staff.Find(s => s.Id == session.InstructorId).FirstOrDefaultAsync();
                if (instructor is not null && !string.IsNullOrWhiteSpace(instructor.UserId))
                    await _notifications.PublishAsync(instructor.UserId, NotificationCategory.NewBooking, payload);
            }

            // Studio admins + managers always get notified.
            await _notifications.PublishToRolesAsync(
                new[] { "Admin", "Manager", "Owner" }, NotificationCategory.NewBooking, payload);
        }
        catch { /* publisher already logs */ }
    });
}

/// <inheritdoc />
public async Task<List<Attendance>> SplitBookingAsync(string attendanceId, List<SplitSeatDto> extraPeople)
{
    var original = await _attendances.Find(a => a.Id == attendanceId).FirstOrDefaultAsync();
    if (original == null) throw new NotFoundException("BOOKING.NOT_FOUND", "Booking not found.");

    var seats = Math.Max(1, original.Quantity);
    if (seats < 2)
        throw new BusinessRuleException("BOOKING.NOT_SPLITTABLE",
            "This booking is for a single seat and cannot be split.");

    // Splitting redistributes seats within an UNPAID pay-at-studio booking. A
    // booking that is already paid, or settled with a package credit, has
    // invoices/credit ledger entries tied to it that a naive split would break.
    if ((original.AmountPaid ?? 0m) > 0m)
        throw new BusinessRuleException("BOOKING.ALREADY_PAID",
            "This booking has already been paid and can't be split. Refund/void it first.");
    if (string.Equals(original.PaymentMethod, "PACKAGE_CREDIT", StringComparison.OrdinalIgnoreCase))
        throw new BusinessRuleException("BOOKING.CREDIT_BOOKING",
            "A credit-settled booking can't be split.");
    if (original.Status is "CANCELLED" or "LATE_CANCEL" or "RESCHEDULED")
        throw new BusinessRuleException("BOOKING.INACTIVE", "This booking is no longer active.");

    var extra = (extraPeople ?? new List<SplitSeatDto>())
        .Where(p => !string.IsNullOrWhiteSpace(p.ClientId)).ToList();
    // Peel off 1..(seats-1) people; the original booking keeps the remainder.
    // This supports both a one-at-a-time UI and a split-all-at-once call.
    if (extra.Count < 1 || extra.Count > seats - 1)
        throw new BusinessRuleException("BOOKING.SPLIT_COUNT",
            $"This booking covers {seats} seats. You can split off between 1 and {seats - 1} " +
            $"{(seats - 1 == 1 ? "person" : "people")}.");

    var session = await _sessions.Find(s => s.Id == original.CalendarSessionId).FirstOrDefaultAsync();
    var perSeat = session?.DropInPrice ?? 0m;

    // Reduce the original row by the number of seats peeled off.
    var remainingSeats = seats - extra.Count;
    await _attendances.UpdateOneAsync(
        a => a.Id == attendanceId,
        Builders<Attendance>.Update
            .Set(a => a.Quantity, remainingSeats)
            .Set(a => a.AmountDueAtStudio, perSeat * remainingSeats));

    // One single-seat row per additional person. Capacity is intentionally NOT
    // re-claimed: the seats were already counted when the original multi-seat
    // booking claimed them, so the class occupancy is unchanged by the split.
    var created = new List<Attendance>();
    foreach (var p in extra)
    {
        var row = new Attendance
        {
            CalendarSessionId = original.CalendarSessionId,
            ClientId = p.ClientId,
            Status = original.Status,
            BookedAt = DateTime.UtcNow,
            BookingReference = GenerateBookingReference(),
            ClientName = string.IsNullOrWhiteSpace(p.ClientName) ? "Walk-in" : p.ClientName,
            ClientPhone = p.ClientPhone,
            BookingSource = original.BookingSource,
            PaymentMethod = "PAY_AT_STUDIO",
            AmountPaid = null,
            AmountDueAtStudio = perSeat,
            Quantity = 1,
        };
        await _attendances.InsertOneAsync(row);
        created.Add(row);
    }

    return created;
}

/// <inheritdoc />
public async Task<Attendance> AdjustAttendeeQuantityAsync(string sessionId, string attendanceId, int newQuantity)
{
    var att = await _attendances.Find(a => a.Id == attendanceId).FirstOrDefaultAsync();
    if (att == null || att.CalendarSessionId != sessionId)
        throw new NotFoundException("BOOKING.NOT_FOUND", "Booking not found on this session.");
    if (att.Status is "CANCELLED" or "LATE_CANCEL" or "RESCHEDULED")
        throw new BusinessRuleException("BOOKING.INACTIVE", "This booking is no longer active.");
    // A bring-a-friend booking is Quantity=2 with one seat free — resizing it would
    // break the promo accounting. Refuse (same spirit as the SplitBooking guards).
    if (att.IsBringAFriend)
        throw new BusinessRuleException("BOOKING.BRING_A_FRIEND",
            "A bring-a-friend booking has a free seat and can't be resized. Remove and re-add to change it.");

    var session = await _sessions.Find(s => s.Id == sessionId).FirstOrDefaultAsync();
    if (session == null) throw new NotFoundException("BOOKING.SESSION_NOT_FOUND", "Session not found.");

    if (newQuantity < 1)
        throw new BusinessRuleException("BOOKING.MIN_ONE_SEAT",
            "A booking must keep at least one seat. Use Remove to cancel it entirely.");

    var isPrivate = string.Equals(session.Format, "PRIVATE", StringComparison.OrdinalIgnoreCase);
    if (isPrivate && newQuantity > 2)
        throw new BusinessRuleException("BOOKING.PRIVATE_DUO_MAX",
            "A private session can hold at most 2 people (duo).");

    var current = Math.Max(1, att.Quantity);
    var delta = newQuantity - current;
    if (delta == 0) return att;

    var isCredit = string.Equals(att.PaymentMethod, "PACKAGE_CREDIT", StringComparison.OrdinalIgnoreCase);
    // A cash/card-paid booking carries an invoice/payment that an in-place resize
    // would desync — refuse it (mirrors SplitBookingAsync's ALREADY_PAID guard).
    // Package-credit and unpaid pay-at-studio bookings are handled below.
    if (!isCredit && (att.AmountPaid ?? 0m) > 0m)
        throw new BusinessRuleException("BOOKING.ALREADY_PAID",
            "This booking has already been paid and can't be resized here. Remove and re-add instead.");

    if (delta > 0)
    {
        // SPM-98 duo bump — lift a 1-on-1 PRIVATE slot's Capacity to 2 so the extra
        // seat fits the atomic guard, but only when the new total is within the duo
        // cap and no OTHER attendee already holds the second seat.
        if (isPrivate && newQuantity == 2 && session.Capacity < 2)
        {
            var othersSeats = session.CurrentBookings - current;
            if (othersSeats > 0)
                throw new BusinessRuleException("BOOKING.PRIVATE_DUO_MAX",
                    "This private session is already shared with another client (duo is full).");
            await _sessions.UpdateOneAsync(
                s => s.Id == sessionId,
                Builders<CalendarSession>.Update.Set(s => s.Capacity, 2));
            session.Capacity = 2;
        }

        // Atomically claim the extra seats — guards the last-spot race exactly like
        // a fresh add. A failed claim means the class is full for the requested grow.
        if (!await TryClaimSessionCapacityAsync(sessionId, delta))
        {
            var spotsLeft = Math.Max(0, session.Capacity - session.CurrentBookings);
            throw new BusinessRuleException("BOOKING.INSUFFICIENT_CAPACITY",
                $"Only {spotsLeft} spot{(spotsLeft == 1 ? "" : "s")} remaining — cannot grow this booking to {newQuantity}.");
        }

        if (isCredit)
        {
            // Debit the additional credits for the extra seats. DeductCreditAsync is
            // atomic: it returns false with NO partial deduction when the wallet
            // can't cover `delta`, so we roll the seat claim back and abort.
            var ok = await _walletService.DeductCreditAsync(
                att.ClientId, session.Format, "qty-adjust-" + att.Id, delta);
            if (!ok)
            {
                await ReleaseSessionCapacityAsync(sessionId, delta);
                throw new BusinessRuleException("BOOKING.CREDIT_DEDUCTION_FAILED",
                    "Not enough package credits to add the extra seat(s). Collect the difference another way.");
            }
        }
    }
    else // delta < 0 — releasing seats
    {
        await _sessions.UpdateOneAsync(s => s.Id == sessionId,
            Builders<CalendarSession>.Update.Inc(s => s.CurrentBookings, delta));
        await _sessions.UpdateOneAsync(
            s => s.Id == sessionId && s.CurrentBookings < 0,
            Builders<CalendarSession>.Update.Set(s => s.CurrentBookings, 0));
        // Refund the freed seats' credits (ledger-driven partial refund).
        if (isCredit)
            await _walletService.RefundPartialCreditByAttendanceWithTrailAsync(att.Id!, -delta);
    }

    // Persist the new seat count. For a pay-at-studio / unpaid booking, re-snapshot
    // the amount due to DropInPrice × newQuantity (mirrors AdminAddStudentAsync /
    // SplitBookingAsync). Credit bookings stay 0đ due — the wallet already absorbed it.
    var update = Builders<Attendance>.Update.Set(a => a.Quantity, newQuantity);
    if (!isCredit)
    {
        var perSeat = session.DropInPrice ?? 0m;
        update = update.Set(a => a.AmountDueAtStudio, perSeat * newQuantity);
    }
    await _attendances.UpdateOneAsync(a => a.Id == att.Id, update);

    // SPM-98 — a decrease that empties a bumped duo PRIVATE restores Capacity to 1.
    if (delta < 0)
        await RestorePrivateCapacityIfEmptyAsync(sessionId);

    att.Quantity = newQuantity;
    return att;
}

/// <inheritdoc />
public async Task<InstructorClientProfileDto?> GetAttendeeProfileAsync(string clientId)

        throw new BusinessRuleException("BOOKING.ALREADY_RESCHEDULED", "This booking has already been rescheduled.");

    if (string.IsNullOrEmpty(attendance.CalendarSessionId))
        throw new BusinessRuleException("BOOKING.MIGRATED_RECORD",
            "This booking is a migrated historical record and cannot be rescheduled.");

    var originalSession = await _sessions.Find(s => s.Id == attendance.CalendarSessionId).FirstOrDefaultAsync()
        ?? throw new NotFoundException("BOOKING.SESSION_NOT_FOUND", "Original session not found.");

    var newSession = await _sessions.Find(s => s.Id == newSessionId).FirstOrDefaultAsync()
        ?? throw new NotFoundException("BOOKING.SESSION_NOT_FOUND", "Target session not found.");

    // Format must match (can't reschedule a GROUP into a PRIVATE or vice versa)
    if (originalSession.Format != newSession.Format)
        throw new BusinessRuleException("BOOKING.FORMAT_MISMATCH",
            $"Cannot reschedule from {originalSession.Format} to {newSession.Format}. Formats must match.");

    // The booking may carry multiple seats (duo=2, group=N); move them all.
    var qty = Math.Max(1, attendance.Quantity);

    // Target session must be in the future
    if (newSession.StartTime <= DateTime.UtcNow)
        throw new BusinessRuleException("BOOKING.SESSION_IN_PAST",
            "Cannot reschedule to a session that has already started.");

    // Target session must have capacity — claimed atomically (after all other
    // validations) so a reschedule can't overbook the destination under concurrency.
    if (!await TryClaimSessionCapacityAsync(newSessionId, qty))
        throw new BusinessRuleException("BOOKING.INSUFFICIENT_CAPACITY",
            "The target session is full. Please choose another class.");

    // ── Execute the reschedule (admin: no policy gates) ──

    // 1. Mark original attendance as RESCHEDULED
    await _attendances.UpdateOneAsync(a => a.Id == attendanceId,
        Builders<Attendance>.Update
            .Set(a => a.Status, "RESCHEDULED")
            .Set(a => a.HasBeenRescheduled, true));

    // 2. Decrement original session's CurrentBookings by the full quantity
    var decFilter = Builders<CalendarSession>.Filter.And(
        Builders<CalendarSession>.Filter.Eq(s => s.Id, originalSession.Id),
        Builders<CalendarSession>.Filter.Gte(s => s.CurrentBookings, qty));
    await _sessions.UpdateOneAsync(decFilter,
        Builders<CalendarSession>.Update.Inc(s => s.CurrentBookings, -qty));

    // 3. Create new attendance on the target session (carries over the original payment/credit)
    var newAttendance = new Attendance
    {
        CalendarSessionId = newSessionId,
        ClientId = attendance.ClientId,
        PackageInstanceId = attendance.PackageInstanceId,
        Status = "BOOKED",
        IsFreeClass = attendance.IsFreeClass,
        CountsTowardsCommission = attendance.CountsTowardsCommission,
        BookedAt = DateTime.UtcNow,
        BookingReference = GenerateBookingReference(),
        ClientName = attendance.ClientName,
        ClientPhone = attendance.ClientPhone,
        ClientEmail = attendance.ClientEmail,
        BookingSource = attendance.BookingSource,
        Goals = attendance.Goals,
        EquipmentType = attendance.EquipmentType,
        PaymentMethod = attendance.PaymentMethod,
        StripePaymentIntentId = attendance.StripePaymentIntentId,
        AmountPaid = attendance.AmountPaid,
        AmountDueAtStudio = attendance.AmountDueAtStudio,
        Quantity = attendance.Quantity,
        RescheduledFromAttendanceId = attendance.Id,
    };
    // Target seat(s) already claimed atomically above; release on insert failure.
    try
    {
        await _attendances.InsertOneAsync(newAttendance);
    }
    catch
    {
        await ReleaseSessionCapacityAsync(newSessionId, qty);
        throw;
    }

    // 4b. SPM-79 — Carry any linked invoice to the new booking. An invoice links to
    // a booking via InvoiceLine.AttendanceId, so re-point every line that pointed at
    // the original attendance to the new attendance's Id (only those lines — never
    // drop or duplicate). This keeps the paid/partial balance attached to the booking
    // the customer is now actually attending, instead of the locked RESCHEDULED row.
    var linkedInvoices = await _invoices.Find(
        Builders<Invoice>.Filter.ElemMatch(i => i.Lines, l => l.AttendanceId == attendanceId)
    ).ToListAsync();
    foreach (var inv in linkedInvoices)
    {
        var changed = false;
        foreach (var line in inv.Lines)
        {
            if (line.AttendanceId == attendanceId)
            {
                line.AttendanceId = newAttendance.Id;
                changed = true;
            }
        }
        if (changed)
            await _invoices.ReplaceOneAsync(i => i.Id == inv.Id, inv);
    }

    // 5. Promote waitlist on original session (slot freed up)
    try { await _waitlistService.TryPromoteNextAsync(originalSession.Id!); }
    catch (Exception ex)
    {
        Console.Error.WriteLine(
            $"[SchedulingService] Waitlist promotion after admin reschedule failed for session {originalSession.Id}: {ex.Message}");
    }

    // 6. Send the same confirmation email the customer reschedule flow uses.
    if (!string.IsNullOrWhiteSpace(attendance.ClientEmail))
    {
        _ = _emailService.SendBookingConfirmationAsync(
            attendance.ClientEmail, attendance.ClientName ?? "Customer",
            newAttendance.BookingReference, newSession.ClassName,
            newSession.InstructorName, newSession.StartTime, newSession.Format,
            newSession.EndTime);
    }

    return new
    {
        success = true,
        newAttendanceId = newAttendance.Id,
        newBookingReference = newAttendance.BookingReference,
        newClassName = newSession.ClassName,
        newStartTime = newSession.StartTime,
        newInstructorName = newSession.InstructorName,
        message = $"Rescheduled to {newSession.ClassName} on {StudioTime.Local(newSession.StartTime):ddd dd MMM, hh:mm tt}."
    };
}

